var _markdown = "\n\n`sa` · 扩展 `default` · SCM 原生命令\n\n共 7 条。写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 医院重生 [#医院重生]\n\n<Opcode id=\"016C\" name=\"ADD_HOSPITAL_RESTART\" member=\"Restart.AddHospital\">\n  加医院重生点（死亡后选最近的）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      016C ADD_HOSPITAL_RESTART\n      in: x, y, z, heading, citiesPassed\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      addHospitalRestart(x, y, z, heading, citiesPassed)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.addHospital(x, y, z, heading, citiesPassed)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 警局重生 [#警局重生]\n\n<Opcode id=\"016D\" name=\"ADD_POLICE_RESTART\" member=\"Restart.AddPolice\">\n  加警局重生点（被捕后选最近的）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      016D ADD_POLICE_RESTART\n      in: x, y, z, heading, citiesPassed\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      addPoliceRestart(x, y, z, heading, citiesPassed)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.addPolice(x, y, z, heading, citiesPassed)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 覆盖下次重生 [#覆盖下次重生]\n\n<Opcode id=\"016E\" name=\"OVERRIDE_NEXT_RESTART\" member=\"Restart.OverrideNext\">\n  强制下一次重生到此坐标。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      016E OVERRIDE_NEXT_RESTART\n      in: x, y, z, heading\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      overrideNextRestart(x, y, z, heading)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.overrideNext(x, y, z, heading)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 取消覆盖 [#取消覆盖]\n\n<Opcode id=\"01F6\" name=\"CANCEL_OVERRIDE_RESTART\" member=\"Restart.CancelOverride\">\n  取消 `016E` 覆盖重生。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      01F6 CANCEL_OVERRIDE_RESTART\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      cancelOverrideRestart()\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.cancelOverride()\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 额外医院点 [#额外医院点]\n\n<Opcode id=\"08DF\" name=\"SET_EXTRA_HOSPITAL_RESTART_POINT\" member=\"Restart.SetExtraHospitalRestartPoint\">\n  额外医院重生点（带半径）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      08DF SET_EXTRA_HOSPITAL_RESTART_POINT\n      in: x, y, z, radius, heading\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      setExtraHospitalRestartPoint(x, y, z, radius, heading)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.setExtraHospitalRestartPoint(x, y, z, radius, heading)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 额外警局点 [#额外警局点]\n\n<Opcode id=\"08E0\" name=\"SET_EXTRA_POLICE_STATION_RESTART_POINT\" member=\"Restart.SetExtraPoliceStationRestartPoint\">\n  额外警局重生点（带半径）。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      08E0 SET_EXTRA_POLICE_STATION_RESTART_POINT\n      in: x, y, z, radius, heading\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      setExtraPoliceStationRestartPoint(x, y, z, radius, heading)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.setExtraPoliceStationRestartPoint(x, y, z, radius, heading)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 任务期间重生 [#任务期间重生]\n\n<Opcode id=\"09FF\" name=\"SET_RESPAWN_POINT_FOR_DURATION_OF_MISSION\" member=\"Restart.SetRespawnPointForDurationOfMission\">\n  任务期间覆盖重生点。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      09FF SET_RESPAWN_POINT_FOR_DURATION_OF_MISSION\n      in: x, y, z\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      setRespawnPointForDurationOfMission(x, y, z)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      Restart.setRespawnPointForDurationOfMission(x, y, z)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
